import base64, os, tempfile, webbrowser, sys, time

HTML_B64 = """"""

def main():
    html = base64.b64decode(HTML_B64)
    tmp = tempfile.NamedTemporaryFile(delete=False, suffix=".html", mode="wb")
    tmp.write(html)
    tmp.close()
    webbrowser.open("file:///" + tmp.name.replace("\\", "/"))
    # Keep process alive briefly so the file exists when browser loads it
    time.sleep(10)
    try:
        os.unlink(tmp.name)
    except Exception:
        pass

if __name__ == "__main__":
    main()
